/**
 * Types for the generated eSpeak-NG module.
 *
 * @remarks `espeak-ng-fr.js` is generated by `scripts/build-espeak-fr.mjs` from
 * `@echogarden/espeak-ng-emscripten`. Only the members the app uses are typed.
 *
 * @packageDocumentation
 */

/** An event emitted during synthesis. */
export interface ESpeakEvent {
  type:
    | 'samplerate'
    | 'sentence'
    | 'word'
    | 'phoneme'
    | 'end'
    | 'mark'
    | 'play'
    | 'msg_terminated'
    | 'list_terminated'
  /** 1-based character position, in the synthesized text, of the word being spoken. */
  text_position: number
  /** Length of the word, for `word` events. */
  word_length: number
  /** Position in the audio, in milliseconds. */
  audio_position: number
  /** For `phoneme` events: the phoneme in IPA. For `word` and `sentence` events: a counter. */
  id?: number | string
}

/** A synthesizer instance. */
export interface ESpeakWorker {
  /** Selects a voice by language code, e.g. `'fr'`. */
  set_voice(name: string): number
  /** Speaking rate, in words per minute. */
  set_rate(rate: number): void
  /**
   * Synthesizes `text` synchronously, calling `callback` with each chunk of audio and its events.
   * The callback returns 0 to continue, 1 to abort.
   */
  synthesize(
    text: string,
    callback: (audio: Int16Array, events: ESpeakEvent[]) => number | boolean,
  ): void
}

/** The initialized Emscripten module. */
export interface ESpeakModule {
  eSpeakNGWorker: new () => ESpeakWorker
}

/**
 * Loads the module.
 *
 * @param options - `locateFile` gives the URL of `espeak-ng-fr.data`. `getPreloadedPackage`
 * supplies its content directly instead, and nothing is fetched.
 */
declare const createModule: (options?: {
  locateFile?: (path: string, prefix: string) => string
  getPreloadedPackage?: (name: string, size: number) => ArrayBuffer
}) => Promise<ESpeakModule>
export default createModule
